import '../../domain/entities/download_entity.dart';
class DownloadModel extends DownloadEntity {
  const DownloadModel({required super.id,required super.taskId,required super.videoId,required super.title,required super.url,required super.downloadUrl,super.thumbnailUrl,required super.quality,required super.format,required super.platform,required super.mediaType,required super.status,required super.progress,super.fileSize,super.downloadedBytes,super.filePath,super.errorMessage,required super.createdAt,super.completedAt,required super.isFavorite,super.duration});
  factory DownloadModel.fromDbMap(Map<String,dynamic> m) => DownloadModel(id:m['id'] as String,taskId:m['task_id'] as String??'',videoId:m['video_id'] as String,title:m['title'] as String,url:m['url'] as String,downloadUrl:m['download_url'] as String,thumbnailUrl:m['thumbnail_url'] as String?,quality:m['quality'] as String,format:m['format'] as String,platform:m['platform'] as String,mediaType:MediaType.values.firstWhere((e)=>e.name==m['media_type'],orElse:()=>MediaType.video),status:DownloadStatus.values.firstWhere((e)=>e.name==m['status'],orElse:()=>DownloadStatus.queued),progress:(m['progress'] as num?)?.toDouble()??0.0,fileSize:m['file_size'] as int?,downloadedBytes:m['downloaded_bytes'] as int?,filePath:m['file_path'] as String?,errorMessage:m['error_message'] as String?,createdAt:DateTime.parse(m['created_at'] as String),completedAt:m['completed_at']!=null?DateTime.parse(m['completed_at'] as String):null,isFavorite:m['is_favorite']==1,duration:m['duration_seconds']!=null?Duration(seconds:(m['duration_seconds'] as num).toInt()):null);
  Map<String,dynamic> toDbMap()=>{'id':id,'task_id':taskId,'video_id':videoId,'title':title,'url':url,'download_url':downloadUrl,'thumbnail_url':thumbnailUrl,'quality':quality,'format':format,'platform':platform,'media_type':mediaType.name,'status':status.name,'progress':progress,'file_size':fileSize,'downloaded_bytes':downloadedBytes,'file_path':filePath,'error_message':errorMessage,'created_at':createdAt.toIso8601String(),'completed_at':completedAt?.toIso8601String(),'is_favorite':isFavorite?1:0,'duration_seconds':duration?.inSeconds};
}
